  $(document).ready(function () {
    updateplay();
    setInterval('updateplay()', 10000);
    var a = $.browser.chrome || $.browser.safari ? document.body : document.documentElement;
    $('#open-prog').on('click', function (b) {
      if ($('#programme').hasClass('open')) {
        $('#programme').removeClass('open').hide();
        $('#open-prog').attr('src', 'img/programme.jpg')
      } else {
        $('#programme').addClass('open').show();
        $('#open-prog').attr('src', 'img/programme.jpg')
      }
      $(a).animate({
        scrollTop: $('#promo').offset().top
      }, 1000)
    });
    $('#close-prog').on('click', function (a) {
      $('#programme').removeClass('open').hide();
      $('#open-prog').attr('src', 'img/programme.jpg')
    });
    $('#embed-close').on('click', function (a) {
      $('#embed-box, #embed-overlay').hide()
    });
    $('#embed-on').on('click', function (a) {
      $('#embed-box, #embed-overlay').show()
    });
    $('#open-popup').on('click', function (a) {
      $('#play-bouton').addClass('pause').css('background-image', 'url(img/lecteur/btn_play.png)');
      soundManager.pause('aSound');
      popup('popup.php', 'Radio Choup', 'resizable=no, location=no, width=320, height=480, menubar=no, status=no, scrollbars=no, menubar=no');
      return false
    });
    $('#open-popup-embed').on('click', function (a) {
      $('#play-bouton').addClass('pause').css('background-image', 'url(img/lecteur/btn_play.png)');
      soundManager.pause('aSound');
      popup('popup.php?f=1', 'Radio Choup', 'toolbar=no, resizable=no, location=no, width=320, height=480, menubar=no, directories=no, status=no, scrollbars=no, menubar=no');
      return false
    });
    $('a[rel="external"]').click(function () {
      this.target = '_blank'
    });
    $('#play-bouton').on('click', function (a) {
      if ($('#play-bouton').hasClass('pause')) {
        soundManager.play('aSound');
        $('#play-bouton').removeClass('pause').css('background-image', 'url(img/lecteur/btn_pause.png)')
      } else {
        $('#play-bouton').addClass('pause').css('background-image', 'url(img/lecteur/btn_play.png)');
        soundManager.pause('aSound')
      }
    });
    $('#play-bouton-pop').on('click', function (a) {
      if ($('#play-bouton-pop').hasClass('pause')) {
        soundManager.play('aSound');
        $('#play-bouton-pop').removeClass('pause').css('background-image', 'url(img/lecteur/btn_pause.png)')
      } else {
        $('#play-bouton-pop').addClass('pause').css('background-image', 'url(img/lecteur/btn_play.png)');
        soundManager.pause('aSound')
      }
    });
    $('#slider-vertical').slider({
      orientation: 'vertical',
      range: 'min',
      min: 0,
      max: 100,
      step: 5,
      value: 80,
      slide: function (a, b) {
        soundManager.setVolume('aSound', b.value)
      }
    });
    $('#slider-horizontal').slider({
      orientation: 'horizontal',
      min: 0,
      max: 100,
      step: 5,
      value: 80,
      slide: function (a, b) {
        soundManager.setVolume('aSound', b.value)
      }
    })
  })
  
  function popup(a, b, c) {
    window.open(a, b, c)
  }
  
  function updateplay() {
    $.ajax({
      url: 'ajax.php?callback=?',
      dataType: 'json',
      complete: function (data) {
        var myObject = eval('(' + data.responseText + ')');
        var cover = myObject.cover;
        $('#radio-itunes').attr('href', myObject.itunes);
        $('#radio-facebook').attr('href', myObject.facebook);
        $('#radio-twitter').attr('href', myObject.twitter);
        $('.radio-titre-titre').html(myObject.title);
        $('.radio-titre-art').html(myObject.artists);
        console.log(myObject.title + ' :: started');
        var term = encodeURI(myObject.artists + ' ' + myObject.title);
        $.getJSON('http://itunes.apple.com/search?term=' + term + '&limit=1&callback=?', function (a) {
          if (a) {
            $('#radio-itunes').attr('href', 'http://clkuk.tradedoubler.com/click?p=23753&a=2170666&url=' + a.results[0].trackViewUrl + '&partnerId=2003')
          }
        })
      }
    })
  }